import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(aLine[i]);
        }

        int n1 = n / 2;
        ArrayList<Long> a1 = new ArrayList<>();
        ArrayList<Long> a2 = new ArrayList<>();

        generateSums1(0, 0, a, n1, m, a1);
        generateSums2(n1, 0, a, n, m, a2);

        Collections.sort(a1);

        long maxSum = 0;
        for (long val : a2) {
            int idx = Collections.binarySearch(a1, m - val);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx > 0) {
                long candidate = a1.get(idx - 1) + val;
                if (candidate > maxSum) {
                    maxSum = candidate;
                }
            }
        }
        System.out.println(maxSum);
    }

    private static void generateSums1(int i, long total, long[] a, int n1, int m, ArrayList<Long> a1) {
        if (i == n1) {
            a1.add(total);
        } else {
            generateSums1(i + 1, (total + a[i]) % m, a, n1, m, a1);
            generateSums1(i + 1, total, a, n1, m, a1);
        }
    }

    private static void generateSums2(int i, long total, long[] a, int n, int m, ArrayList<Long> a2) {
        if (i == n) {
            a2.add(total);
        } else {
            generateSums2(i + 1, (total + a[i]) % m, a, n, m, a2);
            generateSums2(i + 1, total, a, n, m, a2);
        }
    }
}
